<?php
declare(strict_types=1);
namespace App\Command;
use App\Imperium\Runtime\Senate\SubordinatePersonaFreshConsistencyQuestionService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:senate:author-subordinate-persona-fresh-consistency-question',description:'Instantiate the fresh sterile witness and seal its Consistency question pending separately authorized testimony')]
final class SenateAuthorSubordinatePersonaFreshConsistencyQuestionCommand extends Command
{public function __construct(private readonly SubordinatePersonaFreshConsistencyQuestionService$service){parent::__construct();}protected function configure():void{$this->addArgument('baseline-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->service->author((string)$i->getArgument('baseline-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>SUBORDINATE_PERSONA_FRESH_CONSISTENCY_QUESTION_SEALED_PENDING_TESTIMONY_AUTHORIZATION</info> '.$r['question_record_id']);return self::SUCCESS;}}
